379:   const waited =
380:     minutes >= 1
381:       ? `${minutes} ${minutes === 1 ? 'minute' : 'minutes'}`
382:       : `${seconds} ${seconds === 1 ? 'second' : 'seconds'}`;
383:   return `Between games ${gap.afterIndex + 1} and ${gap.beforeIndex + 1} you waited ${waited}.`;
