298: export function bandAt(samples: readonly PulseSample[], tUs: number, baseline: number): ReturnType<typeof bandFor> {
299:   let latest: PulseSample | undefined;
300:   for (const sample of samples) {
301:     if (sample.tUs <= tUs && (!latest || sample.tUs >= latest.tUs)) latest = sample;
302:   }
303:   if (!latest || !isUsableSample(latest, CONFIDENCE_FLOOR)) return null;
304:   if (tUs > latest.tUs + SAMPLE_HOLD_US) return null;
305:   return bandFor(latest.bpm, baseline);
