308: export function elevatedClaim(
309:   samples: readonly PulseSample[],
310:   startUs: number,
311:   stopUs: number,
312:   baseline: number,
313:   blunderTimes: readonly (number | null)[],
314: ): { elevatedMinutes: number; deltaBpm: number } | undefined {
315:   if (blunderTimes.length === 0 || blunderTimes.some((time) => time === null)) return undefined;
316:   const periods = elevatedPeriods(samples, startUs, stopUs, baseline);
317:   const hit = new Set<number>();
318:   for (const time of blunderTimes) {
319:     const index = periods.findIndex((period) => (time ?? -1) >= period.fromUs && (time ?? -1) <= period.toUs);
320:     if (index < 0) return undefined;
321:     hit.add(index);
322:     if (hit.size > 1) return undefined;
323:   }
324:   const period = periods[[...hit][0] ?? -1];
325:   if (!period) return undefined;
326:   return {
327:     elevatedMinutes: (period.toUs - period.fromUs) / 60_000_000,
328:     deltaBpm: Math.round(period.deltaBpm),
329:   };
330: }
331: 
332: function elevatedPeriods(
333:   samples: readonly PulseSample[],
334:   startUs: number,
335:   stopUs: number,
336:   baseline: number,
337: ): { fromUs: number; toUs: number; deltaBpm: number }[] {
338:   const ordered = samples
339:     .filter((sample) => sample.tUs >= startUs && sample.tUs <= stopUs)
340:     .sort((left, right) => left.tUs - right.tUs);
341:   const periods: { fromUs: number; toUs: number; deltaBpm: number }[] = [];
342:   let current: { fromUs: number; toUs: number; deltaBpm: number } | undefined;
343:   for (let index = 0; index < ordered.length; index += 1) {
344:     const sample = ordered[index];
345:     if (!sample || !isUsableSample(sample, CONFIDENCE_FLOOR) || bandFor(sample.bpm, baseline) !== 'elevated') {
346:       current = undefined;
347:       continue;
348:     }
349:     const nextUs = index + 1 < ordered.length ? ordered[index + 1]?.tUs ?? stopUs : stopUs;
350:     const gap = nextUs - sample.tUs;
351:     const end = sample.tUs + (gap > 0 ? Math.min(gap, SAMPLE_HOLD_US) : 0);
352:     if (!current) {
353:       current = { fromUs: sample.tUs, toUs: end, deltaBpm: sample.bpm - baseline };
354:       periods.push(current);
355:     } else {
356:       current.toUs = end;
357:       current.deltaBpm = Math.max(current.deltaBpm, sample.bpm - baseline);
358:     }
359:     const next = ordered[index + 1];
360:     const continues =
361:       next !== undefined &&
362:       gap > 0 &&
363:       gap <= SAMPLE_HOLD_US &&
364:       isUsableSample(next, CONFIDENCE_FLOOR) &&
365:       bandFor(next.bpm, baseline) === 'elevated';
366:     if (!continues) current = undefined;
367:   }
368:   return periods;
369: }
