371: function gapClause(gaps: readonly { afterIndex: number; beforeIndex: number; durationUs: number }[]): string | undefined {
372:   const gap = gaps.reduce<(typeof gaps)[number] | undefined>((best, current) => {
373:     if (!best || current.durationUs > best.durationUs) return current;
374:     return best;
375:   }, undefined);
376:   if (!gap) return undefined;
377:   const minutes = Math.round(gap.durationUs / 60_000_000);
378:   const seconds = Math.max(1, Math.round(gap.durationUs / 1_000_000));
379:   const waited =
380:     minutes >= 1
381:       ? `${minutes} ${minutes === 1 ? 'minute' : 'minutes'}`
382:       : `${seconds} ${seconds === 1 ? 'second' : 'seconds'}`;
383:   return `Between games ${gap.afterIndex + 1} and ${gap.beforeIndex + 1} you waited ${waited}.`;
384: }
